// Some portions generated by Claude
package org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext;

import static org.assertj.core.api.Assertions.assertThat;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.VF;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.assertEvaluationError;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.date;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dt;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.dts;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.integer;
import static org.eclipse.rdf4j.query.algebra.evaluation.function.datetime.ext.DtfLiterals.time;

import java.util.List;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;

/**
 * Edge cases of {@code dtf:dayOfWeek}, {@code dtf:dayOfYear}, {@code dtf:week} and {@code dtf:quarter}.
 */
class DayOfWeekYearWeekQuarterEdgeCaseTest {

	private final DayOfWeek dayOfWeek = new DayOfWeek();
	private final DayOfYear dayOfYear = new DayOfYear();
	private final Week week = new Week();
	private final Quarter quarter = new Quarter();

	@ParameterizedTest
	@CsvSource({ "2024-05-13, 1", "2024-05-14, 2", "2024-05-15, 3", "2024-05-16, 4", "2024-05-17, 5", "2024-05-18, 6",
			"2024-05-19, 7" })
	void dayOfWeekIsIsoMondayOneToSundaySeven(String input, int expected) {
		assertThat(dayOfWeek.evaluate(VF, date(input))).isEqualTo(integer(expected));
	}

	@Test
	void dayOfWeekUsesTheLocalDateNotTheUtcDate() {
		// pins current behaviour: calendar fields are read from the local clock value, the timezone is not applied
		assertThat(dayOfWeek.evaluate(VF, dt("2024-05-19T23:30:00-05:00"))).isEqualTo(integer(7));
		assertThat(dayOfWeek.evaluate(VF, dt("2024-05-20T01:00:00+03:00"))).isEqualTo(integer(1));
	}

	@Test
	void timeInputIsAnEvaluationErrorForAllFourFunctions() {
		for (String lexical : List.of("10:00:00", "10:00:00Z", "24:00:00")) {
			assertEvaluationError("dayOfWeek", () -> dayOfWeek.evaluate(VF, time(lexical)));
			assertEvaluationError("dayOfYear", () -> dayOfYear.evaluate(VF, time(lexical)));
			assertEvaluationError("week", () -> week.evaluate(VF, time(lexical)));
			assertEvaluationError("quarter", () -> quarter.evaluate(VF, time(lexical)));
		}
	}

	@ParameterizedTest
	@CsvSource({ "2024-12-31, 366", "2023-12-31, 365", "2024-01-01, 1", "2100-12-31, 365", "2000-12-31, 366",
			"2024-02-29, 60", "2024-03-01, 61", "2023-03-01, 60" })
	void dayOfYearOnLeapAndNonLeapYears(String input, int expected) {
		assertThat(dayOfYear.evaluate(VF, date(input))).isEqualTo(integer(expected));
	}

	@ParameterizedTest
	@CsvSource({ "2021-01-03, 53", "2024-12-30, 1", "2026-01-01, 1", "2020-12-31, 53", "2027-01-01, 53",
			"2024-01-01, 1", "2023-01-01, 52", "2025-12-29, 1", "2024-12-29, 52" })
	void isoWeekAtYearBoundaries(String input, int expected) {
		assertThat(week.evaluate(VF, date(input))).isEqualTo(integer(expected));
	}

	@ParameterizedTest
	@CsvSource({ "2024-01-01, 1", "2024-03-31, 1", "2024-04-01, 2", "2024-06-30, 2", "2024-07-01, 3", "2024-09-30, 3",
			"2024-10-01, 4", "2024-12-31, 4" })
	void quarterBoundaries(String input, int expected) {
		assertThat(quarter.evaluate(VF, date(input))).isEqualTo(integer(expected));
	}

	@Test
	void dateTimeAndDateTimeStampInputsAreAccepted() {
		assertThat(week.evaluate(VF, dts("2024-12-30T00:00:00Z"))).isEqualTo(integer(1));
		assertThat(quarter.evaluate(VF, dt("2024-03-31T23:59:59.999999999"))).isEqualTo(integer(1));
		assertThat(dayOfYear.evaluate(VF, dts("2024-12-31T23:59:59+14:00"))).isEqualTo(integer(366));
		// 24:00:00 is the start of the next day
		assertThat(dayOfWeek.evaluate(VF, dt("2024-05-17T24:00:00"))).isEqualTo(integer(6));
	}
}
